"""Quest/puzzle item catalogue (port of DmbItems and DmbColourData names; data generated by scripts/import_puzzle_items.py)."""

from __future__ import annotations

import json
from functools import lru_cache
from pathlib import Path

DATA = Path(__file__).resolve().parents[1] / "data" / "puzzle_items.json"
MAX_SLOTS = 8


@lru_cache(maxsize=1)
def _data() -> dict:
    return json.loads(DATA.read_text())


def gd_capitalize(text: str) -> str:
    """GDScript String.capitalize(): snake_case and camelCase to Title Case, with a break between letters and digits."""
    out: list[str] = []
    prev = ""
    for ch in text:
        if ch == "_":
            out.append(" ")
            prev = " "
            continue
        if prev and ((prev.islower() and ch.isupper()) or (prev.isalpha() != ch.isalpha() and prev != " " and (prev.isdigit() or ch.isdigit()))):
            out.append(" ")
        out.append(ch)
        prev = ch
    return " ".join(w[:1].upper() + w[1:].lower() for w in "".join(out).split(" ") if w)


def known(item: str) -> bool:
    return item in _data()["items"] or item.startswith(("sigil_", "cure_fragment_", "token_"))


def name_of(item: str) -> str:
    d = _data()["items"]
    if item in d:
        return d[item]["name"]
    if item.startswith("sigil_"):
        return "Sigil of %s" % gd_capitalize(item[6:])
    if item.startswith("cure_fragment_"):
        return "Cure fragment %s" % item[14:]
    if item.startswith("token_"):
        return "%s token" % gd_capitalize(item[6:])
    return gd_capitalize(item)


def sprite_of(item: str) -> str:
    d = _data()["items"]
    if item in d:
        return d[item]["sprite"]
    if item.startswith("sigil_"):
        return "diamond"
    if item.startswith("cure_fragment_"):
        return "book_red"
    return "box"


def describe(item: str) -> str:
    d = _data()["items"]
    if item in d:
        return d[item]["desc"]
    if item.startswith("sigil_"):
        return "A carved sigil taken from a tower's heart. Another tower will ask for it."
    if item.startswith("cure_fragment_"):
        return "Part of an answer to the sickness in the ground. It wants the other parts."
    if item.startswith("token_"):
        return "A settlement's mark of thanks. Some doors recognise it."
    return "You are not sure what this is for. Yet."


def essence_name(spell: int) -> str:
    names = _data()["essence_names"]
    return names[spell] if 0 <= spell < len(names) else "?"
